fun holder[i: Issue]: set Agent {
  { a: Agent | a.task = i
               and campaignDirAt[campaignOf[i], a.host].checkedOut[i.repo] = a.branch }
}

pred W1_UnclaimedDriftClearsOnClaim {
  some c: Campaign, i: Issue | eventually (i in unclaimedDrift[c]
    and eventually (Now.event = Claim and Now.issue = i
                    and after (i not in unclaimedDrift[c] and i not in Backlog)))
}

pred modelSwitch[r: Role, m: Machine] {
  Now.event = ModelSwitch and no Now.issue and no Who.session
  Who.addressed = { s: Session - Exited | s.role = r and s.machine = m }
  sessionFrame
}

pred S11_MergedButIssueLeftOpen {
  one c: Campaign {
    #c.memberIssues = 1
    always Now.event not in AddMember + RemoveMember
    some i: c.memberIssues {
      eventually (some i.pullRequest and i.pullRequest in Merged and i in Open)
      eventually always (i in Open)
      always not complete[i]
    }
    always not closable[c]
  }
}

pred Sanity {
  twoStepShutdown
  and eventually (some a: Agent | a in Retired)
  and eventually Now.event = Work
  and eventually Now.event = Push
}

pred S6_RepoJoinsMidFlight {
  one c: Campaign {
    #c.memberIssues = 1
    #(c.memberIssues.repo) = 1
    mergeClosed[Issue - c.campaignIssue]
    always Now.event != RemoveMember
    eventually (Now.event = AddMember
                and Now.issue not in c.memberIssues
                and Now.issue.repo not in c.memberIssues.repo)
    eventually (#c.memberIssues = 2 and #(c.memberIssues.repo) = 2
                and (all i: c.memberIssues | complete[i]))
  }
}

pred A17_LiveButNoLongerTheHolder {
  some c: Campaign, a: Agent {
    a.task in c.memberIssues
    eventually (a in Live and liveUnderLocally[c, a.host]
                and a not in holder[a.task])
  }
}

pred launch[m: Machine] {
  m in OnDisk.machine
  Now.issue in Campaign.memberIssues
  not (Now.event = Launch and Where.machine = m and no Where.repo)
}

assert FeaturelessKeeps {
  not (keepDiscipline implies always)
    ((Step.event in WriteArtifact + RenameArtifact and featureless[Step.subject]) implies witnessed in witnessed')
}

